//! Reads the compositor's outputs over `zwlr_output_manager_v1`, from outside
//! the engine.
//!
//! What a display-settings tool does first, and the smallest thing that
//! exercises the whole outside path: protocol code generated by this crate's
//! own build script, marshalled through `crcbl_wayland::ffi`, on a
//! `crcbl_wayland::Display` this crate opens and drives — requests, events,
//! objects the compositor creates (each head and mode), and the read cycle.
//!
//! **Linux and FreeBSD only**, as `crcbl-wayland` is.

#[cfg(desktop_unix)]
mod outputs;
#[cfg(desktop_unix)]
#[allow(
    dead_code,
    reason = "every interface in the XML is generated; the probe uses a few"
)]
mod protocol {
    include!(concat!(env!("OUT_DIR"), "/protocol.rs"));
}

#[cfg(desktop_unix)]
pub use outputs::{Head, Mode, read_heads};
